function setupForm({ doc, updateField, createToast, call }) {
    return {

        //custom action with single button
        actions: [{
            label: "Get Question",
            onClick: () => fnGenerateQuestions({ doc, updateField, createToast, call }) //onclick function 
        }],
    };
}

//function to build a prompt to openAi
function fnBuildPrompt(doc) {
    return `${doc.custom_prompt}
Format the response strictly as a JSON array with the following structure:
[
    {
        "question_category": "<Category Name>",
        "question": "<Question Text>"
    }
]
Do not include any explanations, introductions, or additional text. Only return a valid JSON array.`;
}

// function to Call OpenAI API
function fnFetchQuestionsFromOpenAI(iApiKey, iPrompt) {
    return fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
            "Authorization": `Bearer ${iApiKey}`,
            "Content-Type": "application/json"
        },
        body: JSON.stringify({
            model: "gpt-4o-mini",
            messages: [
                {
                    role: "system",
                    content: "You are a helpful assistant that always responds in valid JSON format without any additional text."
                },
                {
                    role: "user",
                    content: iPrompt
                }
            ],
            max_tokens: 300,
            temperature: 0.3
        })
    }).then(result => result.json());
}

// Parse response from openAI
function fnParseQuestions(idResponse) {
    if (idResponse.choices && idResponse.choices.length > 0) {
        try {
            return JSON.parse(idResponse.choices[0].message.content);
        } catch (error) {
            console.log("Failed to parse JSON from OpenAI:", error);
            return null;
        }
    }
    return null;
}

//Main function that wires everything
function fnGenerateQuestions({ doc, updateField, createToast, call }) {
    const lPrompt = fnBuildPrompt(doc);
    const laQuestion = [];

    createToast({
        title: "LUMI is generating questions...",
        icon: "info",
        iconClasses: 'text-green-600'
    });

    call('frappe.client.get_password', {
        doctype: 'Raven Settings',
        name: 'Raven Settings',
        fieldname: "openai_api_key"
    }).then((apiKey) => {
        return fnFetchQuestionsFromOpenAI(apiKey, lPrompt);
    }).then((response) => {
        const laQuestions = fnParseQuestions(response);
        if (laQuestions) {
            laQuestions.forEach(question => {
                laQuestion.push({ context: question.question_category, question: question.question });
            });
            updateField("custom_lead_questionnaire", laQuestion, () => {
                createToast({
                    title: "LUMI has generated the questions",
                    icon: "check",
                    iconClasses: 'text-green-600'
                });
            });
        } else {
            console.log("Invalid or empty response from OpenAI.");
        }
    }).catch((error) => {
        console.log("LUMI Failed to get questions:", error);
        createToast({
            title: "Something went wrong, try again later.",
            icon: "x",
            iconClasses: 'text-red-600'
        });
    });
}

function setupForm({ doc, call, router, $dialog }) {
    return {
        actions: [{
            "label": "Create Quotation",
            "onClick": () => {
                call('create_quotation',{id_doc: doc}).then((response)=> {
                    if(response.name){
                        router.push({ name: "Quotation", params: { quotationId: response.name } });
                    }else{
                        $dialog({
                          title: "No Item Available",
                          message: response,
                        });
                    }

                });
            }
        } ],
    };
}

function setupForm({ doc }) {
    return {
        actions: [{
            "label": __('Print Preview'),
            "onClick": () => {
                let URL = `/app/print/Quotation/${doc.name}`;
                window.open(URL, '_blank');

            }
        },
        {
            "label": __('Go To Desk'),
            "onClick": () => {
                let URL = `/app/quotation/${doc.name}`;
                window.open(URL, '_blank');

            }
        }
        ],
    };
}

